44	
45	/* QMA7981 register map (datasheet rev 0.96, table 7) */
46	
47	#define QMA7981_REG_CHIP_ID         0x00
48	#define QMA7981_REG_DX_LSB          0x01
49	#define QMA7981_REG_FSR             0x0f
50	#define QMA7981_REG_BW              0x10
51	#define QMA7981_REG_PM              0x11
52	#define QMA7981_REG_SR              0x36
53	
54	/* Soft-reset trigger sequence (write 0xb6 then 0x00 to REG_SR) */
55	
56	#define QMA7981_SOFT_RESET_TRIGGER  0xb6
57	#define QMA7981_SOFT_RESET_RELEASE  0x00
58	
59	/* PM register: 0x80 = mode_active, 100 kHz MCK */
60	
61	#define QMA7981_PM_ACTIVE_100KHZ    0x80
62	
63	/* Full-scale range: ±16 g (1 LSB ≈ 128 μg); measured 1g≈ 128 LSB on this silicon */
64	
65	#define QMA7981_FSR_16G             0x04
66	
67	/* Bandwidth / output data rate: 100 kHz / 1935 ≈ 51.7 Hz */
68	
69	#define QMA7981_BW_52HZ             0xe2
70	
71	/* Valid CHIP_ID range observed across silicon revisions e0..e9.
72	 * Datasheet does not publish a fixed value; we accept this range to
73	 * tolerate v1 (0xe0..0xe7) and v2 (0xe8..0xe9) parts.
74	 */
75	
76	#define QMA7981_CHIP_ID_V3          0x90
77	#define QMA7981_CHIP_ID_MIN         0xe0
78	#define QMA7981_CHIP_ID_MAX         0xe9
79	
80	#define QMA7981_I2C_FREQUENCY       400000
