126	
127	static int qma7981_read_reg(FAR struct qma7981_dev_s *priv,
128	                            uint8_t reg, FAR uint8_t *buf, size_t len)
129	{
130	  struct i2c_msg_s msgs[2];
131	  int ret;
132	
133	  msgs[0].frequency = QMA7981_I2C_FREQUENCY;
134	  msgs[0].addr      = priv->addr;
135	  msgs[0].flags     = 0;
136	  msgs[0].buffer    = &reg;
137	  msgs[0].length    = 1;
138	
139	  msgs[1].frequency = QMA7981_I2C_FREQUENCY;
140	  msgs[1].addr      = priv->addr;
141	  msgs[1].flags     = I2C_M_READ;
142	  msgs[1].buffer    = buf;
143	  msgs[1].length    = len;
144	
145	  ret = I2C_TRANSFER(priv->i2c, msgs, 2);
146	  if (ret < 0)
147	    {
148	      snerr("ERROR: I2C_TRANSFER (read reg 0x%02x) failed: %d\n", reg, ret);
149	    }
150	
151	  return ret;
152	}
153	
154	static int qma7981_write_reg(FAR struct qma7981_dev_s *priv,
155	                             uint8_t reg, uint8_t val)
156	{
157	  struct i2c_msg_s msg;
158	  uint8_t buf[2];
159	  int ret;
160	
161	  buf[0] = reg;
162	  buf[1] = val;
163	
164	  msg.frequency = QMA7981_I2C_FREQUENCY;
165	  msg.addr      = priv->addr;
166	  msg.flags     = 0;
167	  msg.buffer    = buf;
168	  msg.length    = 2;
169	
170	  ret = I2C_TRANSFER(priv->i2c, &msg, 1);
171	  if (ret < 0)
172	    {
173	      snerr("ERROR: I2C_TRANSFER (write reg 0x%02x) failed: %d\n", reg, ret);
174	    }
175	
176	  return ret;
177	}
178	
179	static int qma7981_chip_init(FAR struct qma7981_dev_s *priv)
180	{
181	  uint8_t chip_id = 0;
182	  int ret;
183	
184	  /* Read CHIP_ID to confirm the device responds */
185	
186	  ret = qma7981_read_reg(priv, QMA7981_REG_CHIP_ID, &chip_id, 1);
187	  if (ret < 0)
188	    {
189	      snerr("ERROR: failed to read QMA7981 CHIP_ID\n");
190	      return ret;
191	    }
192	
193	  if (chip_id != QMA7981_CHIP_ID_V3 &&
194	      (chip_id < QMA7981_CHIP_ID_MIN || chip_id > QMA7981_CHIP_ID_MAX))
195	    {
196	      snerr("ERROR: unexpected QMA7981 CHIP_ID 0x%02x\n", chip_id);
197	      return -ENODEV;
198	    }
199	
200	  sninfo("QMA7981 detected, CHIP_ID=0x%02x\n", chip_id);
201	
202	  /* Soft-reset: write trigger then release. */
203	
204	  qma7981_write_reg(priv, QMA7981_REG_SR, QMA7981_SOFT_RESET_TRIGGER);
205	  up_udelay(100);
206	  qma7981_write_reg(priv, QMA7981_REG_SR, QMA7981_SOFT_RESET_RELEASE);
207	
208	  /* Wait for the soft-reset to complete before configuring registers.
209	   * Datasheet specifies a ready time after reset; 10 ms is safe.
210	   */
211	
212	  up_mdelay(10);
213	
214	  /* Configure: active mode, ±8 g range, ~52 Hz ODR.
215	   * Retry PM write a few times: the power-management register may
216	   * reject writes issued too soon after reset.
217	   */
218	
219	  ret = qma7981_write_reg(priv, QMA7981_REG_PM,  QMA7981_PM_ACTIVE_100KHZ);
220	  if (ret < 0)
221	    {
222	      up_mdelay(10);
223	      ret = qma7981_write_reg(priv, QMA7981_REG_PM,
224	                              QMA7981_PM_ACTIVE_100KHZ);
225	    }
226	
227	  qma7981_write_reg(priv, QMA7981_REG_FSR, QMA7981_FSR_16G);
228	  qma7981_write_reg(priv, QMA7981_REG_BW,  QMA7981_BW_52HZ);
229	
230	  return OK;
231	}
