247	static ssize_t qma7981_read(FAR struct file *filep, FAR char *buffer,
248	                            size_t buflen)
249	{
250	  FAR struct inode *inode = filep->f_inode;
251	  FAR struct qma7981_dev_s *priv = inode->i_private;
252	  struct qma7981_data_s sample;
253	  uint8_t raw[6];
254	  int ret;
255	
256	  if (buflen < sizeof(sample))
257	    {
258	      return -EINVAL;
259	    }
260	
261	  /* Burst-read DX_LSB..DZ_MSB (6 bytes).  Each axis is a 14-bit value left-
262	   * aligned in a little-endian 16-bit field; we shift right by 2 bits to
263	   * recover the signed sample.
264	   */
265	
266	  ret = qma7981_read_reg(priv, QMA7981_REG_DX_LSB, raw, sizeof(raw));
267	  if (ret < 0)
268	    {
269	      return ret;
270	    }
271	
272	  sample.x = ((int16_t)((raw[1] << 8) | raw[0])) >> 2;
273	  sample.y = ((int16_t)((raw[3] << 8) | raw[2])) >> 2;
274	  sample.z = ((int16_t)((raw[5] << 8) | raw[4])) >> 2;
275	
276	  memcpy(buffer, &sample, sizeof(sample));
277	  return sizeof(sample);
278	}
