286	/****************************************************************************
287	 * Public Functions
288	 ****************************************************************************/
289	
290	int qma7981_register(FAR const char *devpath,
291	                     FAR struct i2c_master_s *i2c, uint8_t addr)
292	{
293	  FAR struct qma7981_dev_s *priv;
294	  int ret;
295	
296	  DEBUGASSERT(devpath != NULL && i2c != NULL);
297	
298	  priv = kmm_zalloc(sizeof(*priv));
299	  if (priv == NULL)
300	    {
301	      snerr("ERROR: failed to allocate QMA7981 device\n");
302	      return -ENOMEM;
303	    }
304	
305	  priv->i2c  = i2c;
306	  priv->addr = addr;
307	
308	  ret = qma7981_chip_init(priv);
309	  if (ret < 0)
310	    {
311	      snwarn("WARNING: QMA7981 not detected on bus (errno %d).  "
312	             "Driver will register but read() will fail with EIO.  "
313	             "Check that the EYE board has the accelerometer "
314	             "populated and that I2C0 (SDA=GPIO4, SCL=GPIO5) is "
315	             "wired correctly.\n", ret);
316	    }
317	
318	  ret = register_driver(devpath, &g_qma7981_fops, 0666, priv);
319	  if (ret < 0)
320	    {
321	      snerr("ERROR: register_driver(%s) failed: %d\n", devpath, ret);
322	      kmm_free(priv);
323	      return ret;
324	    }
325	
326	  sninfo("QMA7981 registered at %s (addr 0x%02x)\n", devpath, addr);
327	  return OK;
328	}
